const csv = $json;
const body = typeof $json === 'string' ? $json : ($json.body ?? '');
const text = body || '';

const lines = text.trim().split(/\r?\n/);
let close = null;
if (lines.length >= 2) {
  const cols = lines[1].split(',');
  if (cols.length >= 7) close = Number(cols[6]);
}
return [{ json: { macro_source: 'stooq', dxy_close: close } }];

const articles = ($json.articles || []).slice(0, 15).map(a => ({
  title: a.title,
  url: a.url,
  source: a.domain || a.sourceCountry || a.source,
  date: a.seendate
}));
return [{ json: { source: 'GDELT', items: articles } }];

const agentOutput = $json?.agent_output || $json?.output || $json?.text || JSON.stringify($json);
const outputStr = typeof agentOutput === 'string' ? agentOutput : JSON.stringify(agentOutput, null, 2);

const buyMatch = outputStr.match(/BUY:\s*(\d+)%/i);
const sellMatch = outputStr.match(/SELL:\s*(\d+)%/i);
const waitMatch = outputStr.match(/WAIT:\s*(\d+)%/i);

const buyPct = buyMatch ? parseInt(buyMatch[1]) : null;
const sellPct = sellMatch ? parseInt(sellMatch[1]) : null;
const waitPct = waitMatch ? parseInt(waitMatch[1]) : null;

const createBar = (pct, max = 100, width = 20) => {
  if (pct === null) return '';
  const filled = Math.round((pct / max) * width);
  const empty = width - filled;
  return '█'.repeat(filled) + '░'.repeat(empty) + ` ${pct}%`;
};

const header = `🟡 XAUUSD - SIGNAL & BRIEF\n⏱ ${new Date().toLocaleString()}\n━━━━━━━━━━━━━━━━━━━━\n`;

let probBox = '';
if (buyPct !== null || sellPct !== null || waitPct !== null) {
  probBox = `\n📊 PROBABILITÉS:\n`;
  if (buyPct !== null) probBox += `🟢 BUY:  ${createBar(buyPct)}\n`;
  if (sellPct !== null) probBox += `🔴 SELL: ${createBar(sellPct)}\n`;
  if (waitPct !== null) probBox += `🟡 WAIT: ${createBar(waitPct)}\n`;
  probBox += `\n`;
}

const message = header + probBox + outputStr;

return [{ json: { text: message } }];

const j = $json;

const price = Number(j.price);
const symbol = j.symbol || 'XAU/USD';
const dt = j.datetime || new Date().toISOString();

if (!Number.isFinite(price)) {
  return [{ json: { ok: false, error: 'Price missing', raw: j } }];
}

return [{
  json: {
    ok: true,
    symbol,
    price,
    datetime: dt,
    change: j.change ?? null,
    percent_change: j.percent_change ?? null,
    open: j.open ?? null,
    high: j.high ?? null,
    low: j.low ?? null,
    prev_close: j.previous_close ?? null
  }
}];

const inputs = $input.all().map(i => i.json || {});

const toNumber = (v) => {
  if (v === null || v === undefined) return null;
  const n = Number(v);
  return Number.isFinite(n) ? n : null;
};

const pickFirst = (getterList) => {
  for (const fn of getterList) {
    try {
      const v = fn();
      if (v !== undefined && v !== null) return v;
    } catch (e) {}
  }
  return null;
};

const flattenNews = (arr) => {
  if (!Array.isArray(arr)) return [];
  return arr
    .filter(x => x && typeof x === 'object')
    .map(x => ({
      title: x.title ?? x.headline ?? x.name ?? null,
      url: x.url ?? x.link ?? null,
      source: x.source ?? x.domain ?? null,
      date: x.date ?? x.pubDate ?? x.seendate ?? null
    }))
    .filter(x => x.title);
};

const bestContext = inputs.find(j =>
  j.gdeltItems || j.rssItems || j.xau || j.macro
) || {};

let xauPrice = pickFirst([
  () => bestContext?.xau?.price,
  () => bestContext?.xau?.close,
  () => bestContext?.price,
  () => bestContext?.xauusd_price,
  () => bestContext?.xauusd_proxy_price
]);
xauPrice = toNumber(xauPrice);

let dxy = pickFirst([
  () => bestContext?.macro?.dxy_close,
  () => bestContext?.dxy_close,
  () => bestContext?.macro?.dxy,
]);
dxy = toNumber(dxy);

let us10y = pickFirst([
  () => bestContext?.macro?.us10y_close,
  () => bestContext?.us10y_close,
  () => bestContext?.macro?.us10y,
]);
us10y = toNumber(us10y);

let gdeltItems = [];
let rssItems = [];

gdeltItems = gdeltItems.concat(flattenNews(bestContext?.gdeltItems));
rssItems = rssItems.concat(flattenNews(bestContext?.rssItems));

for (const j of inputs) {
  if (j?.source === 'GDELT' && Array.isArray(j?.items)) {
    gdeltItems = gdeltItems.concat(flattenNews(j.items));
  }
  if (Array.isArray(j?.gdeltItems)) gdeltItems = gdeltItems.concat(flattenNews(j.gdeltItems));
  if (Array.isArray(j?.rssItems)) rssItems = rssItems.concat(flattenNews(j.rssItems));

  if (j?.title && (j?.link || j?.url)) {
    rssItems.push({ title: j.title, url: j.link ?? j.url, date: j.pubDate ?? j.date ?? null, source: j.source ?? null });
  }
}

const uniqByTitle = (arr) => {
  const seen = new Set();
  const out = [];
  for (const it of arr) {
    const key = (it.title || '').trim().toLowerCase();
    if (!key || seen.has(key)) continue;
    seen.add(key);
    out.push(it);
  }
  return out;
};

gdeltItems = uniqByTitle(gdeltItems).slice(0, 20);
rssItems = uniqByTitle(rssItems).slice(0, 20);

const headlines = [
  ...gdeltItems.map(x => `GDELT: ${x.title}`),
  ...rssItems.map(x => `RSS: ${x.title}`)
].slice(0, 25);

const newsText = headlines.join('\n');

const blob = newsText.toLowerCase();
const highImpactKeywords = [
  'cpi', 'inflation', 'pce', 'nfp', 'nonfarm', 'payroll',
  'fomc', 'fed', 'powell', 'rate decision', 'interest rate decision',
  'jobless claims', 'gdp'
];
const highImpactDetected = highImpactKeywords.some(k => blob.includes(k));

const context = {
  generatedAt: new Date().toISOString(),
  xau: {
    symbol: (bestContext?.xau?.symbol ?? 'XAUUSD'),
    price: xauPrice
  },
  macro: {
    dxy_close: dxy,
    us10y_close: us10y,
    highImpactDetected
  },
  news: {
    gdeltItems,
    rssItems,
    newsText
  }
};

return [{ json: context }];
